INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (3,'Green','Light Brown','Medium and Straight','Light','Blustering','Particularly low or highvoice','Loyal to a benefactor, patron, or employer','Arrogance','Greatergood','Breathy – With loud breathing noises.','Blouse','Affectionate','The nearest city gates are shut, with many soldiers stationed on the walls. All visitors are being turned away, but some locals pass along the story of rioting and murder.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (4,'Hazel','Leather Black','Medium and Curly','LightTan','Rude','Speaks in an unusually formal manner','Captivated by aromantic interest','Envies another creature’s possessions or station','Life','Brittle – You sound as if you are about to cry.','Crop Top','Aggressive','A tinker''s wagon has gone into a ditch and broken a wheel. The tinker passes many rumors (all false) of the surrounding area. He offers his services at a great discount if the party helps him right his spilled wagon and goods. All his trinkets are cursed.');
