INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (8,'Gold','Light Ash Blonde','Bald','Brown','Hottempered','Uses flowery speech or long words','Out for revenge','Prone to sudden suspicion','Greed','Flat – Spoken in a voice that does not go up and down.','Sarong','Angry','A local druid has posted signs asking for hunters to register their names with him before taking any game. 3 arrows are piercing one of them, and others are torn or ripped. A few stags antlers have been tied to tree trunks, as if in defiance.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (9,'Gray','Light Blonde','Dreadlocks','Black','Irritable','Frequently uses the wrong word','Dedicated to fulfilling a personal lifegoal','Shameful or scandalous history','Might','Fruity – Deep and strong in a pleasant way.','Uniforms','Angsty','A shipwreck on a nearby coast is swarming with orc raiders');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (10,'Topaz','Hot Toffee','Mohawk','Bronze','Ponderous','Uses colorful oaths and exclamations','I would die to recover an ancient artifact of my faith that was lost long ago.','Secret crime or misdeed','Pain','Grating – Unpleasant and annoying.','Religious clothing','Annoyed','A traveling family warns of swarms of mating stirge in the nearby area, and many angry farmers who are blaming the disinterest of the local ruler for their dead cattle (and children).');
