INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (12,'Red','Havana Brown','Wavy','Gray','Suspicious','Prone to predictions of doom','I owe me life to the priest who took me in when my parents died.','Foolhardy bravery','Slaughter','Gruff – Rough, low, and speaks in short huffs.','Cape','Worried','Strangers report a dangerous section of road that passes through a dark wood. Murderous kenku have taken the road and are extorting every hapless traveler.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (13,'Purple','Beeline Honey','Curly','Ash','conscientiousness','Fidgets','Everything I do is for the common people.','I killed my family.','Community','Guttural – Deep and made at the back of your throat.','Poncho','Antagonistic','Every night ravenous swarms of Grimlocks boil up out of the Underdark to terrorize a village that is slowly losing the fight.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (14,'Pale Brown','Medium Champagne','Curls','White','agreeableness','Squints','I will do anything to protect the temple where I served.','I have an obvious tell when I lie.','Fairness','Half Singing – Lyrical, light and whimsical','Shawl','Apathetic','The hanging corpse of a local Ranger hangs from a tree, his hands and feet have been removed and cannot be found. A bloody carving in his naked chest may be identified as the feyclan mark of a family of Quicklings. There are skull-dangles throughout the forest and many traps.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (15,'Orange','Espresso','Bob','Red','openness','Stares into the distance','I seek to preserve a sacred text that my enemies consider heretical and seek to destroy.','Nobody can know anything about my history, as they will inevitably use it against me.','Honor','High Pitched – Very high and shrill.','Abaya','Arrogant','A group of Githzerai suddenly teleport into the area, see the party and yell at them to run, flee! FLEE! A group of Githyanki teleport in 1 minute later');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (16,'Sky','French Roast','Wispy Bangs','Purple','extroversion','Chews something','I fleeced the wrong person and must work to ensure that this individual never crosses paths with me or those I care about.','I always keep a hand on my coin purse, and my weapon','Logic','Hoarse – Low rough and strained.','Beret','Avoidant','A sea journey is stopped by calm winds and the haunting predations of an angry revenant - the spirit of the true captain, a woman murdered 40 years previously.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (17,'Dark Blue','Light Cool Brown','Wolf Cut','Yellow','accepting','Paces','I owe everything to my mentor--a horrible person who''s probably rotting in jail somewhere.','I always position myself so that I can see everyone, and every entrance and exit in the room.','Responsibility','Honeyed – Falsely sweet voice.','Kasaya','Awestruck','A murderous cabal of Wereseals (yes they existed in 2e) have camped in some coastal caves. They are preying on passing ships as well as passing caravans. One of them wears a headband that keeps it in telepathic contact with its true master, an offshore Aboleth.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (18,'Black','Light Brown','Shag with Bangs','Orange','adaptable','Taps fingers','Somewhere out there I have a child who doesn''t know me. I''m making the world better for him or her.','Paranoid doesn''t even begin to describe me.','Tradition','Husky – Low, rumbling and easy.','kimono','Benevolent','Two tribes of goblins engaged in murderous warfare on one another. One chieftain wears a cursed ring that drives the owner to obsessively eat the flesh of its own species.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (19,'Mahogany','Ruby Fusion','Braid','Blue','affable','Bites fingernails','I come from a noble family, and one day I''ll reclaim my lands and title from those who stole them from me.','I let down my guard around friends, and am usually unprepared if anything happens.','Change','Lisp – Drags some consonant sounds with their tounge.','Lederhosen','Belligerent','A torrent of rain, high winds and lightning drive the party underground to take shelter. There they find a mysterious cave tucked away in a side passage - the bodies of two strange races held in stasis.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (20,'Moss','Crushed Garnet','Pigtail','Green','broad-minded','Twirls hair or tugs beard','A powerful person killed someone I love. Someday soon, I''ll have my revenge.','I rely on my friends for almost everything, because I don''t trust myself.','Creativity','Low – Quiet and difficult to hear / in a deep voice.','Turban','Biased','The party finds a ray gun. It fires twice reliably, and then only ever again if the owner is near death (under 1/4 of total HP). Range: 120 Damage: 2d6 necrotic and 5% chance to disintegrate target. This automatically works on a critical hit. The gun will function 1d20+1 times before burning out. It cannot be repaired. Its owner, a young Illithid hunter, may come looking for it.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (21,'Emerald','Blowout Burgundy','Pony Knot','Orc','charismatic','Blinks often','I swindled and ruined a person who didn''t deserve it. I seek to atone for my misdeeds but might never be able to forgive myself.','I don''t have any flaws. I am perfect (In my eyes).','Freedom','Matter of fact – blunt and flat.','Trench Coat','Bigoted','A serial graffiti artist has been creating disturbing works of art on local buildings and the some of the residents have had psychological breaks after looking at them for too long.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (22,'Ice Blue','Chocolate Brown','Bandana Wrap','Goblin green','compassionate','Looks to the left often','I''m trying to pay off an old debt I owe to a generous benefactor.','I''m the smartest one here, and don''t let anyone else tell you otherwise.','Independence','Modulated – Controlled and pleasant to listen to.','Robe','Brave','The All Fool''s Day Parade appears on the horizon. The King of Fools has many followers, all of them quite mad, but jolly. Some hundreds walking, riding, operating strange contraptions, come closer. Chaotic, wild music and singing, sinuous and whirling dancers may just draw the party along for a celebration that will last days, possibly weeks before the party is released, forever changed.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (23,'Clockwork','Dark Golden Brown','Fishtail Braid','Dirty','competent','Changes tone of voice at odd points','My ill-gotten gains go to support my family.','I can''t stand still for longer than ten seconds.','Nolimits','Monotonous – Boring because it does not change in loudness or become higher or lower.','Vest','Broadminded','Two boys are fighting over a traveling satchel in the middle of the road. A squirrel is perched on the case and is watching the fight, very agitated, and chittering loudly. Overhead a jackdaw swoops one boy again and again, making lots of noise.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (24,'Marble','Chocolate Cherry','Bow','rosy pale','confident','Pauses while speaking a lot','Something important was taken from me, and I aim to steal it back.','I find it hard to concentrate on one thing, and often find my mind wandering.','Whimsy','Orotund – Loud and clear.','Tunic','Buoyant','Reports of a girl lost in the nearby area. They say she had gone missing before, and had been found in a local valley, stone cold and refusing to speak.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (25,'Candy','Midnight Ruby','Head Scarf','Light','congenial','Offers unnecessary details','I will become the greatest thief that ever lived.','I am invincible!','Balance','Penetrating – So high or loud that it makes you uncomfortable.','Corset','Callous','A group of thieves have set up a traveling medicine show, selling patent medicines and manuals of healthy living. They are drugging the wealthy who stop by, and replacing them with members of a tribe of dopplegangers who have threatened the gang with death if they do not comply.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (26,'Ink','Reddish Blonde','Flip Over','Normal','courageous','Rubbing nose','I''m guilty of a terrible crime. I hope I can redeem myself for it.','I am mortal. Everything and Everything can kill me. Please help.','Knowledge','Plummy – This word shows that you dislike people who speak like this.','Chaperon','Calm','One of the party wakes up with bloody hands and a letter in their pocket. The letter is written in a rare language, and is printed on human skin. Its contents are a lie, and are just the beginning of a campaign of psychological torture by a leprechaun that has latched onto the player and who remains nearby, invisible.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (27,'Topaz','Magenta','Space Buns','Exotic','creative','Pointing a finger','Someone I loved died because of a mistake I made. That will never happen again.','I have crippling depression, but I try to hide it.','Liveandletlive','Quietly – In a quiet voice.','Breeches','Caring','A huge blackened circle of scorched and burnt earth and trees. In the center of the circle is the body of a paladin. In his hand is a Holy Avenger. The Avenger is awakened. Its name is <insert cool name here>');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (28,'Burgundy','Indigo Blue','Hippie Braids','Medium','determined','Sweats excessively','My instrument is my most treasured possession, and it reminds me of someone I love.','I seem to lose everything good in my life.I am hesitant about new things.','Moderation','Raucous – Loud and sounds rough.','Fur','Cheerless','A collector has decided one of the party members should belong to her collection of beautiful specimens. The collector starts leaving gifts for the party member to find, becoming increasingly romantic, until one night when the collector (use an intelligent outsider) comes for her prize.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (29,'Ruby','Purple Rage','High Bun','Native','discreet','Swallows constantly','Someone stole my precious instrument, and someday I''ll get it back.','I always take charge of the situation, especially when someone else is meant to.','Neutrality','Ringing – very loud and clear.','Brocatelle','Closed-minded','A drunken sailor tells tale of his ship that was taken by "reavers", murderous cannibals who ripped his crewmates apart. He is lying. It wasn''t his ship. But a pack of kuo-toa have been plundering the local shipping lanes and soon they will grow bored of waiting for prey and attack the nearby population.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (30,'Sapphire','Aquamarine','Twists and Curls','Terra Cotta','driven','Arms crossed defensively','I want to be famous, whatever it takes.','I am extremely jealous of everyone for one thing or another.','People','Rough – Not soft and is unpleasant to listen to.','Camlet','Cold','Tornado!');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (31,'Olive','Platinum','Blowout','Fawn','empathic','Chain smokes','I idolize a hero of the old tales and measure my deeds against that person''s.','I don''t take orders well. I work alone.','Aspiration','Shrill – Very loud, high, and unpleasant.','Apron','Commanding','A local pie-eating contest is being held. The prize is a small Bag of Pies, a minor magic item that conjures 1 type of any kind of fruit pie per day. The entry price is 20 coins.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (32,'Peach','Titanium','Short Quiff','Gold','enthusiastic','Chews on lips','I will do anything to prove myself superior to me hated rival.','I hate those who differ from my opinions.','Discovery','Silvery – Clear, light, and pleasant.','Band','Competitive','A dog barks at the party, insistently. Tries to get the party to follow. If they do, the dog will lead them to a ramshackle cabin where the dogs friends, a group of Jackalwere (use stats, but just describe as particular dog breed), who have been doing this to travelers for a while, and have amassed a decent pile of treasure.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (33,'Crystal','Emerald','Medium Side Swept','Umber','exuberant','Chews on fingernails','I would do anything for the other members of my old troupe.','I don''t care if I kill. We all die eventually... right?','Glory','Singsong – Rises and falls in a musical way.','Brales','Conceited','A dimensional gate opens and a contingent of 255 Modrons spill forth, measuring and collecting samples of everything (including lifeforms)');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (34,'Emerald','Royal Navy','Short Brush Over with Undercut','Caramel','fair','Eyes that dart around a lot','I have a family, but I have no idea where they are. One day, I hope to see them again.','Don''t get on my bad side. If you do... Well, just watch out, OK?','Nation','Slurred – Slow or lagging speach pattern.','Breeches','Concerned','A planar resonance occurs and forces open a True Gate to the demi-plane of Ravenloft (The Mists)');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (35,'Sun','Rich Eggplant','Short Sides, Long Top Style','Peach','friendly','Whistles while walking','I worked the land, I love the land, and I will protect the land.','I am always smug and self centred.','Redemption','Small – A small voice or sound is quiet.','Chalnse','Conciliatory','A smear of 3 grey oozes pick up the party''s trail in civilization and are pursued relentlessly');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (36,'Amethyst','Sweet Mint','Short','Oyster white','gregarious','Smiles a lot','A proud noble once gave me a horrible beating, and I will take my revenge on any bully I encounter.','I make a joke out of everything.','Self-knowledge','Smoky – Sexually attractive in a slightly mysterious way.','Cloak','Confident','At a crossroads, on a hill, near a forest, a family of Ankheg are engaged in an all out war with a large force of Aarakocra. The bird-folk send a scout to determine the party''s intentions.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (37,'Mint','Jade','Afro','Mocha','helpful','Whispers into another''s ear often','My tools are symbols of my past life, and I carry them so that I will never forget my roots.','I speak very loudly, and have a tendency to yell.','Creativity','Softly Spoken – A quiet gentle voice.','Ferronniere','Condescending','Tidal Wave!');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (38,'Dark Purple','Sky Blue','Straight','Auburn','honest','Beats on surfaces with hands and/or fingers','I protect those who cannot protect themselves.','Once I set my mind on something, nothing can stop me, even a God.','Charity','Sotto Voce – A very quiet voice.','Gorget','Contrarian','A bronze dagger, rusty with age, is lying in the dirt of a wilderness crossroads. It is the last memory of a Nothic, bound to the old blade. The dagger is actually +1 due to its masterwork quality, but the Nothic will whisper insane threats and ramblings of nonsense, while promising untold power if the user will only free him. This cursed blade can be destroyed as any artifact would.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (39,'Ash gray','Perwinkle','Collected','Almond','humble','Seems to "zone out" when music is playing','I wish my childhood sweetheart had come with me to pursue my destiny.','I am extremely belligerent towards another race.','Honor','Stentorian – Loud and severe.','Liripipe','Critical','The Dance of the Skeletons, a celebration of the Deity of the Dead, marked by debauchery and music, has been interrupted by a huge swarm of Peryton, come to feed in the breeding season.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (40,'Vanilla','Amber','geometric','Vanilla','independent','Holds eye contact when interacting','The workshop where I learned my trade is the most important place in the world to me.','I dont'' need help. Must I do everything myself?','Greed','Strangulated – One that someone stops before they finish making it.','Ruff','Cynical','A noise, getting louder and louder becomes a human falling towards the party''s position at terminal velocity. The human misses the party when hitting the ground, creating a 10'' hole and knocking the party prone. 50/50% chance the human has actually survived.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (41,'Mint','Shaded(Ombre)','Long bound','Bronze','insightful','Stands too close to others','I created a great work for someone, and then found them unworthy to receive it. I''m still looking for someone worthy.','No one appreciates me. I''m useless.','Respect','Strident – Loud and unpleasant.','Leaves','Dark','A group of men burst out of the nearby tavern, fighting bloodily with knives and skillets, chairs and broken tankards. The fighting engulfs the party.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (42,'Palatinate','Glossy Dark Red Waves','Tonsured','Copper','intelligent','Talks loudly','I owe my guild a great debt for forging me into the person I am today.','I am oblivious to my surroundings.','Might','Taut – Shows someone is nervous or angry.','Gambason','Daring','A small boy appears in the party''s camp one night, sitting by the fire. He never speaks and cannot be touched, not through being incorporeal, but through a repulsion field that is beyond 30th level magic. The boy stays one hour and then vanishes. This event occurs every night for a week. On the last night one of the players finds a ring on their finger. This ring contains 1 dose of a poison that will kill any creature in the known realms without a saving throw. It also kills the poisoner.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (43,'Maize','Black Hair with Cherry Highlights','Ship','Steal','kind','Wears vivid, loud colors','I pursue wealth to secure someone''s love.','I can often too enamored with alcohol.','Change','Thick – Voice sounds less clear because of an emotion.','Buckle','Defeatist','A bard''s camp has been set up, and a wooden stage is filled with a group of 6 minstrels singing and playing music. A large crowd has gathered and are clapping and stomping. An 18th level rogue is in the crowd. He has been hired to steal something from each of the party members. His boss is a Medusa.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (44,'Khaki','Mahogany and Cherry','Bangs','Coral Pink','loyal','Cracking knuckles','One day I will return to my guild and prove that I am the greatest artisan of them all.','I have a really bad habit I can''t break.','Might','Thin – High and unpleasant to listen to.','Chemise','Defensive','A purple worm hole opens in civilization overnight. If explored, a new campaign should begin.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (45,'Prussian Blue','Cherry Red Highlights on Dark Hair',NULL,'Wine Red','mindful','Looks down when walking','I will get revenge on the evil forces that destroyed my place of business and ruined my livelihood.','I won''t let myself feel emotions.','Aspiration','Throaty – Low and seems to come from deep in your throat.','Dress','Depressed','An old woman approaches the party on the road. She is marked with deformity and is overburdened with baggage. If the party approaches, the ruse will be revealed to be a Doppleganger who is carrying 2 (or 4) Mimics. They have been doing this a long time, but the DG hates his slavery and will flee, leaving the mimics behind if the battle turns.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (46,'Raisin Black','Golden Brown','Princess Belle','Corpse Blue','optimistic','Apologizes often','Nothing is more important than the other members of my hermitage, order, or association.','I can''t let others see my inner turmoil.','Retribution','Tight – Shows that you are nervous or annoyed.','Sackcloth','Detached','A local wood-elf tribe, known to be friendly in trade, have suddenly shut their forest-gates and are turning all visitors away. Rumors of a new sickness swirl.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (47,'Redwood','Deep Brunette with Caramel Highlights','Mermaid Hair','Lotus','patient','Mumbles','I entered seclusion to hide from the ones who might still be hunting me. I must someday confront them.','I am extremely blunt, and have no tact whatsoever.','Respect','Toneless – Does not express any emotion.','Sash','Determined','Ogres have gathered in a nearby valley in their teeming hundreds. They have come to choose a new King, and the blood-games are about to begin. They will last for 10 days and after the King is crowned, they will rampage on the surrounding area, concentrating on live slaves and food for the coronation feast. The King''s name is always Bubba.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (48,'rosy Brown','Bright Blue Highlights','Multicolored','Midnight Blue','persistent','Yawns a lot','I''m still seeking the enlightenment I pursued in my seclusion, and it still eludes me.','I have been cursed, but nobody can know.','Independence','Tremulous – It is not steady because you are afraid or excited.','Bodysuit','Diplomatic','Zombies, risen from a nearby graveyard are bothering travelers. If the party intervenes they discover the zombies are asking for parley. They are not mindless. They are not hungry. They are something new. They need help.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (49,'Rust','Black Blue','Princesses´Buns','Mud  Green','precise','Laughs a lot','I entered seclusion because I loved someone I could not have.','I don''t like to fully commit myself unless the odds are overwhelmingly in my favour.','People','Wheezy – Has difficulty breathing.','Girdle','Disdainful','A threesome of Shadows have taken up residence in civilization. They have been unable to keep their hunger under control, and they have been seen. The party discovers this when they enter the streets and find the city in a religious fervor, the Temples preaching overtime at the Evil in their Midst.');
INSERT INTO description_model(description_Id,description_Eyes,description_Hair_Color,description_Hair_Style,description_Skin,description_Trait,description_Mannerism,description_Bond,description_Flaw,description_Ideal,description_Voice,description_Clothing,description_Attitute,description_Plothook) VALUES (50,'Royal Purple','Blended Fall','Begger','Kobold Brown','reliable','Never says "please" or "thank you"','Should my discovery come to light, it could bring ruin to the world.','I have dyslexia; I find it difficult to read and write.','Master','Wobbly – Unstable tone due to fright or emotions.','Nighshirt','Disgusted','A mixed collection of Golems are rampaging across the countryside. They appear to be free-willed.');
