INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (1,'Talons','You have talons that you can use to make unarmed strikes. When you hit with them, the strike deals 1d6 + your Strength modifier slashing damage, instead of the bludgeoning damage normal for an unarmed strike.','natural attack');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (2,'Wind Caller','Starting at 3rd level, you can cast the gust of wind spell with this trait, without requiring a material component. Once you cast the spell with this trait, you can''t do so again until you finish a long rest. You can also cast the spell using any spell slots you have of 2nd level or higher. Intelligence, Wisdom, or Charisma is your spellcasting ability for when you cast gust of wind with this trait (choose when you select this race).','spell: gust of wind');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (3,'Flight','Because of your wings, you have a flying speed equal to your walking speed. You can''t use this flying speed if you''re wearing medium or heavy armor.','movement speed');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (4,'Darkvision','You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can''t discern color in darkness, only shades of grey.','vision');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (5,'Celestial Resistance','"You have resistance to necrotic and radiant damage."','damage resistance');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (6,'Celestial Legacy','"You know the light cantrip. Once you reach 3rd level, you can cast the lesser restoration spell once with this trait, and you regain the ability to do so when you finish a long rest. Once you reach 5th level, you can cast the daylight spell once with this trait, and you regain the ability to do so when you finish a long rest. Charisma is your spellcasting ability for these spells."','spell: light, [3] lesser restoration, [5] daylight');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (7,'Long-Limbed','"When you make a melee attack on your turn, your reach for it is 5 feet greater than normal."','bonus text');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (8,'Powerful Build','"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."','bonus text');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (9,'Sneaky','"You are proficient in the Stealth skill."','skill: Stealth');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (10,'Surprise Attack','"If you surprise a creature and hit it with an attack on your first turn in combat, the attack deals an extra 2d6 damage to it. You can use this trait only once per combat."','bonus text');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (11,'Fey Ancestry','"You have advantage on saving throws you make to avoid or end the charmed condition on yourself."','advantage');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (12,'Fey','"Your creature type is fey, rather than humanoid."','bonus text');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (13,'Charge','"If you move at least 30 feet straight toward a target and then hit it with a melee weapon attack on the same turn, you can immediately follow that attack with a bonus action, making one attack against the target with your hooves."','bonus text');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (14,'Hooves','"Your hooves are natural melee weapons, which you can use to make unarmed strikes. If you hit with them, you deal bludgeoning damage equal to 1d4 + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."','natural attack');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (15,'Equine Build','"You count as one size larger when determining your carrying capacity and the weight you can push or drag. In addition, any climb that requires hands and feet is especially difficult for you because of your equine legs. When you make such a climb, each foot of movement costs you 4 extra feet, instead of the normal 1 extra foot."','bonus text');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (16,'Survivor','"You have proficiency in one of the following skills of your choice: Animal Handling, Medicine, Nature, or Survival."','skill: 1: Animal Handling, Medicine, Nature, Survival');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (17,'Draconic Ancestry','"You have draconic ancestry. Choose one type of dragon from the Draconic Ancestry table. Your breath weapon and damage resistance are determined by the dragon type, as shown in the table."','bonus table: draconic weapon');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (18,'Breath Weapon','"You can use your action to exhale destructive energy. Your draconic ancestry determines the size, shape, and damage type of the exhalation. When you use your breath weapon, each creature in the area of the exhalation must make a saving throw, the type of which is determined by your draconic ancestry. The DC for this saving throw equals 8 + your Constitution modifier + your proficiency bonus. A creature takes 2d6 damage on a failed save, and half as much damage on a successful one. The damage increases to 3d6 at 6th level, 4d6 at 11th level, and 5d6 at 16th level. After you use your breath weapon, you can''t use it again until you complete a short or long rest."','natural attack');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (19,'Damage Resistance','"You have resistance to the damage type associated with your draconic ancestry."','damage resistance');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (20,'Keen Senses','You have proficiency in the Perception skill.','skill: Perception');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (21,'Trance','Elves don''t need to sleep. Instead, they meditate deeply, remaining semiconscious, for 4 hours a day. (The Common word for such meditation is "trance.") While meditating, you can dream after a fashion; such dreams are actually mental exercises that have become reflexive through years of practice. After resting in this way, you gain the same benefit that a human does from 8 hours of sleep.','bonus text');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (22,'Elf Weapon Training','You have proficiency with the longsword, shortsword, shortbow, and longbow.','weapon: Longsword, Shortsword, Shortbow, Longbow');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (23,'WizCantrip','You know one cantrip of your choice from the wizard spell list. Intelligence is your spellcasting ability for it.','cantrip: 1: Wizard');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (24,'Dwarven Resilience','You have advantage on saving throws against poison, and you have resistance against poison damage.','bonus text');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (25,'Dwarven Combat Training','You have proficiency with the battleaxe, handaxe, light hammer, and warhammer.','weapon: Battleaxe, Handaxe, Light Hammer, Warhammer');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (26,'Tool Proficiency','You gain proficiency with the artisan''s tools of your choice: Smith''s tools, brewer''s supplies, or mason''s tools.','bonus text');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (27,'Stonecunning','Whenever you make an Intelligence (History) check related to the origin of stonework, you are considered proficient in the History skill and add double your proficiency bonus to the check, instead of your normal proficiency bonus.','bonus text');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (28,'Dwarven Toughness','Your hit point maximum increases by 1, and it increases by 1 every time you gain a level.','bonus text');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (29,'Dwarven Armor Training','You have proficiency with light and medium armor.','armor: Light Armor, Medium Armor');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (30,'Superior Darkvision','Accustomed to the depths of the Underdark, you have superior vision in dark and dim conditions. You can see in dim light within 120 feet of you as if it were bright light, and in darkness as if it were dim light. You can''t discern color in darkness, only shades of gray.','bonus text');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (31,'Sunlight Sensitivity','You have disadvantage on attack rolls and on Wisdom (Perception) checks that rely on sight when you, the target of your attack, or whatever you are trying to perceive is in direct sunlight.','bonus text');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (32,'Drow Magic','You know the dancing lights cantrip. When you reach 3rd level, you can cast the faerie fire spell once with this trait; you regain the ability to cast it when you finish a long rest. When you reach 5th level, you can also cast the darkness spell once per day with this trait; you regain the ability to cast it when you finish a long rest. Charisma is your spellcasting ability for these spells.','cantrip: dancing light spell:[3] faerie fire, [5] darkness');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (33,'Drow Weapon Training','You have proficiency with rapiers, shortswords, and hand crossbows.','weapon: Rapier, Shortsword, Hand Crossbow');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (34,'Fleet of Foot','Your base walking speed increases to 35 feet.','speed: 35w');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (35,'Mask of the Wild','You can attempt to hide even when you are only lightly obscured by foliage, heavy rain, falling snow, mist, and other natural phenomena.','bonus text');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (36,'Gnome Cunning','You have advantage on all Intelligence, Wisdom, and Charisma saving throws against magic.','bonus text');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (37,'Natural Illusionist','You know the minor illusion cantrip. Intelligence is your spellcasting ability for it.','cantrip: minor illusion');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (38,'Speak with Small Beasts','Through sounds and gestures, you can communicate simple ideas with Small or smaller beasts. Forest gnomes love animals and often keep squirrels, badgers, rabbits, moles, woodpeckers, and other creatures as beloved pets.','bonus text');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (39,'Artificer''s Lore','Whenever you make an Intelligence (History) check related to magic items, alchemical objects, or technological devices, you can add twice your proficiency bonus, instead of any proficiency bonus you normally apply.','bonus text');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (40,'Tinker','You have proficiency with artisan''s tools (tinker''s tools). Using those tools, you can spend 1 hour and 10 gp worth of materials to construct a Tiny clockwork device (AC 5, 1 hp). The device ceases to function after 24 hours (unless you spend 1 hour repairing it to keep the device functioning), or when you use your action to dismantle it; at that time, you can reclaim the materials used to create it. You can have up to three such devices active at a time.','bonus text');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (41,'Clockwork Toy','This toy is a clockwork animal, monster, or person, such as a frog, mouse, bird, dragon, or soldier. When placed on the ground, the toy moves 5 feet across the ground on each of your turns in a random direction. It makes noises as appropriate to the creature it represents.','bonus text');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (42,'Fire Starter','The device produces a miniature flame, which you can use to light a candle, torch, or campfire. Using the device requires your action.','bonus text');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (43,'Music Box','When opened, this music box plays a single song at a moderate volume. The box stops playing when it reaches the song''s end or when it is closed.','bonus text');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (44,'Skill Versatility','You gain proficiency in two skills of your choice.','skill: 2: Any');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (45,'Menacing','You gain proficiency in the Intimidation skill.','skill: Intimidation');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (46,'Relentless Endurance','When you are reduced to 0 hit points but not killed outright, you can drop to 1 hit point instead. You can''t use this feature again until you finish a long rest.','bonus text');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (47,'Savage Attacks','When you score a critical hit with a melee weapon attack, you can roll one of the weapon''s damage dice one additional time and add it to the extra damage of the critical hit.','bonus text');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (48,'Lucky','When you roll a 1 on an attack roll, ability check, or saving throw, you can reroll the die and must use the new roll.','bonus text');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (49,'Brave','You have advantage on saving throws against being frightened.','bonus text');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (50,'Halfling Nimbleness','You can move through the space of any creature that is of a size larger than yours.','bonus text');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (51,'Naturally Stealthy','You can attempt to hide even when you are obscured only by a creature that is at least one size larger than you.','bonus text');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (52,'Stout Resilience','You have advantage on saving throws against poison, and you have resistance against poison damage.','bonus text');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (53,'Hellish Resistance','You have resistance to fire damage.','bonus text');
INSERT INTO feature_model(feature_ID,feature_Name,feature_Description,feature_Kind_Of) VALUES (54,'Infernal Legacy','You know the thaumaturgy cantrip. Once you reach 3rd level, you can cast the hellish rebuke spell as a 2nd-level spell with this trait; you regain the ability to cast it when you finish a long rest. Once you reach 5th level, you can also cast the darkness spell once per day with this trait; you regain the ability to cast it when you finish a long rest. Charisma is your spellcasting ability for these spells.','cantrip: thaumaturgy spell: [3] hellish rebuke, [5] darkness');
